1	/**
2	 * GDPR: customers/redact
3	 *
4	 * Shopify sends this when a customer requests deletion of their data,
5	 * or when 10 days have passed after a shop uninstalls the app.
6	 *
7	 * You must delete all personally identifiable information for this customer.
8	 *
9	 * Required for Shopify App Store listing.
10	 * https://shopify.dev/docs/apps/build/privacy-law-compliance
11	 */
12	import type { ActionFunctionArgs } from "react-router";
