16	export const action = async ({ request }: ActionFunctionArgs) => {
17	  const { shop, payload } = await authenticate.webhook(request);
18	
19	  const customerEmail = payload?.customer?.email;
20	
21	  try {
22	    if (customerEmail) {
23	      // Delete all PII for this customer: waitlist entries contain email addresses
24	      await db.waitlistEntry.deleteMany({
25	        where: { shop, email: customerEmail },
26	      });
27	    }
28	  } catch {
29	    // Shopify requires a 200 response regardless of errors
30	  }
31	
32	  return new Response();
