1	import { AppProvider } from "@shopify/shopify-app-react-router/react";
2	import { useState } from "react";
3	import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
4	import { Form, redirect, useActionData, useLoaderData } from "react-router";
5	
6	import { login } from "../../shopify.server";
7	import { loginErrorMessage } from "./error.server";
8	
9	export const loader = async ({ request }: LoaderFunctionArgs) => {
10	  const url = new URL(request.url);
11	  const shop = url.searchParams.get("shop");
12	
13	  // If we're inside the embedded app (shop param present), redirect to /app
14	  // instead of showing the login form — the app shell handles auth via session tokens.
15	  if (shop) {
16	    throw redirect(`/app?shop=${encodeURIComponent(shop)}`);
17	  }
18	
19	  // If the request is inside an iframe (embedded), also redirect.
20	  // This prevents the bare login form from appearing inside Shopify admin.
21	  if (url.searchParams.get("embedded") === "1") {
22	    throw redirect("/app");
23	  }
24	
25	  // Check for Shopify's sec-fetch headers — if the request comes from an iframe
26	  // context (embedded app) but without a shop param, redirect to /app so the
27	  // Shopify App Bridge can handle re-authentication automatically.
28	  const secFetchDest = request.headers.get("sec-fetch-dest");
29	  if (secFetchDest === "iframe") {
30	    throw redirect("/app");
31	  }
32	
33	  const errors = loginErrorMessage(await login(request));
34	
35	  return { errors };
36	};
37	
38	export const action = async ({ request }: ActionFunctionArgs) => {
39	  const errors = loginErrorMessage(await login(request));
40	
41	  return {
42	    errors,
43	  };
44	};
45	
46	export default function Auth() {
47	  const loaderData = useLoaderData<typeof loader>();
48	  const actionData = useActionData<typeof action>();
49	  const [shop, setShop] = useState("");
50	  const { errors } = actionData || loaderData;
51	
52	  return (
53	    <AppProvider embedded={false}>
54	      <s-page>
55	        <Form method="post">
56	        <s-section heading="Log in">
57	          <s-text-field
58	            name="shop"
59	            label="Shop domain"
60	            details="example.myshopify.com"
61	            value={shop}
62	            onChange={(e) => setShop(e.currentTarget.value)}
63	            autocomplete="on"
64	            error={errors.shop}
65	          ></s-text-field>
66	          <s-button type="submit">Log in</s-button>
67	        </s-section>
68	        </Form>
69	      </s-page>
70	    </AppProvider>
71	  );
72	}
