1	import type { LoginError } from "@shopify/shopify-app-react-router/server";
2	import { LoginErrorType } from "@shopify/shopify-app-react-router/server";
3	
4	interface LoginErrorMessage {
5	  shop?: string;
6	}
7	
8	export function loginErrorMessage(loginErrors: LoginError): LoginErrorMessage {
9	  if (loginErrors?.shop === LoginErrorType.MissingShop) {
10	    return { shop: "Please enter your shop domain to log in" };
11	  } else if (loginErrors?.shop === LoginErrorType.InvalidShop) {
12	    return { shop: "Please enter a valid shop domain to log in" };
13	  }
14	
15	  return {};
16	}
