2	 * Claude Hub Agent Client
3	 *
4	 * Calls global agents from Claude Hub (localhost:3847) during development.
5	 * Drop this file into any Boldteq app's utils/ folder to use agents.
6	 *
7	 * Usage:
8	 *   import { callAgent, listAgents, getAgent } from "~/utils/agent.server";
9	 *
10	 *   // Call an agent with a task
11	 *   const result = await callAgent("quill", "Write an app store listing for Pinzo");
12	 *
13	 *   // List all available agents
14	 *   const agents = await listAgents();
15	 *
16	 *   // Get a specific agent's details
17	 *   const quill = await getAgent("quill");
18	 */
19	
20	const CLAUDE_HUB_URL = process.env.CLAUDE_HUB_URL || "http://localhost:3847";
21	
22	export interface Agent {
23	  filename: string;
24	  name: string;
25	  description: string;
26	  model: string;
27	  body: string;
28	  raw: string;
29	  updatedAt: string;
30	}
