1	/**
2	 * Simple in-memory rate limiter for public API endpoints.
3	 *
4	 * Uses a sliding-window counter per key (typically shop+IP or shop).
5	 * Automatically cleans up expired entries to prevent memory leaks.
6	 *
7	 * This is a single-instance rate limiter — suitable for single-server
8	 * deployments (Railway, Render, etc.). For multi-instance deployments,
9	 * replace with Upstash Redis or similar distributed rate limiter.
10	 */
11	
12	interface RateLimitEntry {
13	  count: number;
14	  resetAt: number;
15	}
16	
17	const store = new Map<string, RateLimitEntry>();
18	
19	// Cleanup expired entries every 60 seconds
20	const CLEANUP_INTERVAL = 60_000;
21	let lastCleanup = Date.now();
22	
23	function cleanup() {
24	  const now = Date.now();
25	  if (now - lastCleanup < CLEANUP_INTERVAL) return;
26	  lastCleanup = now;
27	  for (const [key, entry] of store) {
28	    if (entry.resetAt <= now) {
29	      store.delete(key);
30	    }
31	  }
32	}
33	
34	/**
35	 * Check if a request should be rate-limited.
36	 *
37	 * @param key — unique key for the rate limit bucket (e.g. "zip-check:shop.myshopify.com:1.2.3.4")
38	 * @param limit — max requests allowed in the window
39	 * @param windowMs — time window in milliseconds
40	 * @returns { limited: boolean, remaining: number, resetAt: number }
41	 */
42	export function rateLimit(
43	  key: string,
44	  limit: number,
45	  windowMs: number,
46	): { limited: boolean; remaining: number; resetAt: number } {
47	  cleanup();
48	
49	  const now = Date.now();
50	  const entry = store.get(key);
51	
52	  if (!entry || entry.resetAt <= now) {
53	    // First request or window expired — start new window
54	    store.set(key, { count: 1, resetAt: now + windowMs });
55	    return { limited: false, remaining: limit - 1, resetAt: now + windowMs };
56	  }
57	
58	  entry.count++;
59	  if (entry.count > limit) {
60	    return { limited: true, remaining: 0, resetAt: entry.resetAt };
61	  }
62	
63	  return { limited: false, remaining: limit - entry.count, resetAt: entry.resetAt };
64	}
