66	/**
67	 * Extract client IP from request headers (works behind proxies like Railway, Vercel).
68	 */
69	export function getClientIp(request: Request): string {
70	  return (
71	    request.headers.get("cf-connecting-ip") ||
72	    request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ||
73	    request.headers.get("x-real-ip") ||
74	    "unknown"
75	  );
76	}
77	
78	/**
79	 * Build a rate-limit Response with proper headers.
80	 */
81	export function rateLimitResponse(
82	  resetAt: number,
83	  corsHeaders: Record<string, string>,
84	): Response {
85	  return new Response(
86	    JSON.stringify({ error: "Too many requests. Please try again later." }),
87	    {
88	      status: 429,
89	      headers: {
90	        ...corsHeaders,
91	        "Retry-After": String(Math.ceil((resetAt - Date.now()) / 1000)),
92	      },
93	    },
94	  );
95	}
